css:
.reader-layout {
  --official-hairline: 1px;
  --official-section-gap: 1.75rem;
  --official-control-transition: 120ms ease;
}
.document-reader {
  box-sizing: border-box;
  min-inline-size: 0;
  padding: var(--reader-document-padding, 28px 32px 48px);
  font-family: var(--reader-font-family);
  font-size: var(--markdown-font-size);
  font-weight: var(--reader-font-weight);
  line-height: var(--markdown-line-height);
  border-radius: var(--reader-radius);
}
.document-reader > div {
  min-inline-size: 0;
}
.document-reader .markdown-paragraph {
  margin-block: var(--reader-paragraph-spacing);
  overflow-wrap: anywhere;
  text-wrap: pretty;
}
.document-reader .markdown-paragraph:first-child {
  margin-block-start: 0;
}
.document-reader .markdown-paragraph:last-child {
  margin-block-end: 0;
}
.document-reader .markdown-heading {
  font-family: var(--reader-heading-font, var(--reader-font-family));
  color: var(--reader-heading-text);
  letter-spacing: 0;
  text-wrap: balance;
}
.document-reader .markdown-heading--h1 {
  margin-block: var(--reader-h1-margin, 2.1rem 1rem);
  font-size: var(--reader-h1-size);
  font-weight: var(--reader-h1-weight);
  line-height: var(--reader-h1-line-height);
}
.document-reader .markdown-heading--h2 {
  margin-block: var(--reader-h2-margin, 1.8rem 0.8rem);
  font-size: var(--reader-h2-size);
  font-weight: var(--reader-h2-weight);
  line-height: var(--reader-h2-line-height);
}
.document-reader .markdown-heading--h3 {
  margin-block: var(--reader-h3-margin, 1.5rem 0.65rem);
  font-size: var(--reader-h3-size);
  font-weight: var(--reader-h3-weight);
  line-height: var(--reader-h3-line-height);
}
.document-reader .markdown-heading--h4 {
  margin-block: var(--reader-h4-margin, 1.3rem 0.55rem);
  font-size: var(--reader-h4-size);
  font-weight: var(--reader-h4-weight);
}
.document-reader .markdown-heading--h5 {
  margin-block: var(--reader-h5-margin, 1.15rem 0.5rem);
  font-size: var(--reader-h5-size);
  font-weight: var(--reader-h5-weight);
}
.document-reader .markdown-heading--h6 {
  margin-block: var(--reader-h6-margin, 1rem 0.45rem);
  font-size: var(--reader-h6-size);
  font-weight: var(--reader-h6-weight);
}
.document-reader .markdown-heading > a {
  color: inherit;
  text-decoration: none;
}
.document-reader .markdown-link {
  color: var(--reader-link);
  text-decoration-line: underline;
  text-decoration-thickness: var(--reader-link-decoration-thickness, 1px);
  text-underline-offset: var(--reader-link-underline-offset, 0.18em);
}
.document-reader .markdown-link:hover {
  text-decoration-thickness: calc(var(--reader-link-decoration-thickness, 1px) + 1px);
}
.document-reader strong {
  font-weight: var(--reader-strong-weight, 700);
}
.document-reader em {
  font-style: italic;
}
.document-reader mark {
  padding-inline: 0.16em;
  border-radius: var(--reader-mark-radius, 3px);
  background: var(--reader-mark-bg);
  color: var(--reader-mark-text);
}
.document-reader ul,
.document-reader ol {
  margin-block: var(--reader-list-spacing);
  padding-inline-start: var(--reader-list-indent);
}
.document-reader li {
  margin-block: var(--reader-list-item-spacing);
}
.document-reader li::marker {
  color: var(--reader-accent);
  font-weight: 700;
}
.document-reader .contains-task-list {
  padding-inline-start: 0;
  list-style: none;
}
.document-reader .task-list-item {
  display: grid;
  grid-template-columns: 1.25rem minmax(0, 1fr);
  align-items: start;
  gap: 0.45rem;
}
.document-reader .task-list-item input[type="checkbox"] {
  inline-size: 1rem;
  block-size: 1rem;
  margin: 0.28em 0 0;
  border-radius: var(--reader-checkbox-radius, 4px);
  accent-color: var(--reader-checkbox-checked-bg);
}
.document-reader .task-list-item.is-checked {
  color: var(--reader-task-done);
  text-decoration: line-through;
}
.document-reader .markdown-quote {
  margin-block: var(--official-section-gap);
  padding: var(--reader-quote-padding);
  border-inline-start: var(--reader-quote-border-width, 3px) solid var(--reader-quote-border);
  border-radius: var(--reader-quote-radius);
  background: var(--reader-quote-bg);
  color: var(--reader-quote-text);
}
.document-reader .markdown-quote > :first-child {
  margin-block-start: 0;
}
.document-reader .markdown-quote > :last-child {
  margin-block-end: 0;
}
.document-reader hr {
  margin-block: calc(var(--official-section-gap) * 1.4);
  border: 0;
  border-block-start: var(--official-hairline) solid var(--reader-rule);
}
.document-reader .markdown-inline-code {
  padding: 0.12em 0.38em;
  border-radius: var(--reader-code-radius);
  background: var(--reader-inline-code-bg);
  color: var(--reader-inline-code-text);
  font-family: var(--reader-monospace-font);
  font-size: var(--reader-code-font-size);
}
.document-reader .markdown-code-block {
  position: relative;
  overflow: auto;
  margin-block: var(--official-section-gap);
  padding: var(--reader-code-padding);
  border: var(--reader-code-border-width, 1px) solid var(--reader-code-border);
  border-radius: var(--reader-code-radius);
  background: var(--reader-code-bg);
  color: var(--reader-code-text);
  box-shadow: var(--reader-code-shadow, none);
}
.document-reader .markdown-code-block code {
  font-family: var(--reader-monospace-font);
  font-size: var(--reader-code-font-size);
  line-height: var(--reader-code-line-height, 1.55);
  tab-size: 2;
}
.document-reader .markdown-code-block[data-language]::before {
  content: attr(data-language);
  position: sticky;
  inset-inline-start: 100%;
  display: block;
  inline-size: max-content;
  margin: calc(var(--reader-code-padding-block, 14px) * -0.45) 0 0;
  font-family: var(--reader-monospace-font);
  font-size: 0.72rem;
  opacity: 0.68;
}
.document-reader .token.comment {
  color: var(--reader-syntax-comment);
  font-style: italic;
}
.document-reader .token.keyword {
  color: var(--reader-syntax-keyword);
  font-weight: 650;
}
.document-reader .token.string {
  color: var(--reader-syntax-string);
}
.document-reader .token.function {
  color: var(--reader-syntax-function);
}
.document-reader .markdown-table-wrapper {
  position: relative;
  overflow: auto;
  scrollbar-gutter: stable;
  margin-block: var(--official-section-gap);
  border-radius: var(--reader-table-radius);
  box-shadow: var(--reader-table-scroll-shadow, none);
}
.document-reader .markdown-table {
  inline-size: 100%;
  border-collapse: var(--reader-table-border-collapse, separate);
  border-spacing: var(--reader-table-border-spacing, 0);
  color: var(--reader-table-text);
  font-size: var(--reader-table-font-size, 0.94rem);
  font-variant-numeric: tabular-nums;
}
.document-reader .markdown-table-caption {
  padding: 0 0 0.65rem;
  color: var(--reader-muted);
  text-align: start;
  font-size: 0.82rem;
}
.document-reader .markdown-table-cell {
  min-block-size: var(--reader-table-row-height);
  padding: var(--reader-table-cell-padding);
  border-block-end: var(--reader-table-cell-border-width, 1px) solid var(--reader-table-border);
  text-align: start;
  vertical-align: top;
}
.document-reader .markdown-table-cell--head,
.document-reader .markdown-table-header-cell {
  position: sticky;
  inset-block-start: 0;
  z-index: 2;
  background: var(--reader-table-head);
  color: var(--reader-heading-text);
  font-weight: var(--reader-table-heading-weight, 700);
}
.document-reader .markdown-table-row:nth-child(even) .markdown-table-cell {
  background: var(--reader-table-stripe);
}
.document-reader .markdown-table-row:hover .markdown-table-cell {
  background: var(--reader-table-row-hover);
}
.document-reader .callout {
  position: relative;
  display: grid;
  gap: var(--reader-callout-gap, 8px);
  margin-block: var(--official-section-gap);
  padding: var(--reader-callout-padding);
  border: var(--reader-callout-border-width, 1px) solid var(--reader-callout-border);
  border-radius: var(--reader-callout-radius);
  background: var(--reader-callout-bg);
  color: var(--reader-callout-text);
  box-shadow: var(--reader-callout-shadow, none);
}
.document-reader .callout-title {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  color: var(--reader-callout-title);
  font-weight: 750;
}
.document-reader .callout-title::before {
  content: "";
  flex: 0 0 auto;
  inline-size: var(--reader-callout-icon-size, 0.72rem);
  block-size: var(--reader-callout-icon-size, 0.72rem);
  border-radius: var(--reader-callout-icon-radius, 50%);
  background: var(--reader-accent);
}
.document-reader .callout-content > :first-child {
  margin-block-start: 0;
}
.document-reader .callout-content > :last-child {
  margin-block-end: 0;
}
.document-reader .callout-warning {
  --reader-callout-border: var(--reader-color-orange);
}
.document-reader .callout-danger,
.document-reader .callout-error {
  --reader-callout-border: var(--reader-color-red);
}
.document-reader .callout-success,
.document-reader .callout-tip {
  --reader-callout-border: var(--reader-color-green);
}
.document-reader .callout-info,
.document-reader .callout-note {
  --reader-callout-border: var(--reader-color-blue);
}
.document-reader .callout-quote {
  --reader-callout-border: var(--reader-muted);
}
.reader-toolbar {
  min-block-size: var(--reader-toolbar-height);
  padding: var(--reader-toolbar-padding, 8px 12px);
  border-block-end: var(--reader-toolbar-border-width, 1px) solid var(--reader-border);
  background: var(--reader-toolbar-bg);
  box-shadow: var(--reader-toolbar-shadow, none);
}
[data-theme-layout-scope="toolbar-group"] {
  gap: var(--reader-toolbar-gap);
}
.reader-toolbar button {
  min-inline-size: var(--reader-toolbar-button-size);
  min-block-size: var(--reader-toolbar-button-size);
  padding-inline: var(--reader-control-padding-inline, 10px);
  border-radius: var(--reader-control-radius);
  background: var(--reader-control-bg);
  box-shadow: var(--reader-control-shadow);
  transition: background var(--official-control-transition), box-shadow var(--official-control-transition);
}
.reader-toolbar button:hover {
  background: var(--reader-tree-row-hover);
}
.reader-toolbar button:active {
  box-shadow: inset 0 1px 2px rgb(0 0 0 / 18%);
}
.reader-toolbar button:focus-visible {
  outline: 2px solid var(--reader-accent);
  outline-offset: 2px;
}
.reader-toolbar button:disabled {
  opacity: 0.5;
  box-shadow: none;
}
.file-tree {
  box-sizing: border-box;
  min-inline-size: 0;
  padding: var(--reader-panel-padding);
  background: var(--reader-panel-bg);
  color: var(--reader-text);
}
.file-tree__row {
  min-block-size: var(--reader-file-tree-row-height);
}
[data-theme-layout-scope="file-tree-indicator"] {
  min-block-size: var(--reader-file-tree-row-height);
  padding-inline: var(--reader-tree-row-padding, 6px);
  border-radius: var(--reader-tree-row-radius, var(--reader-control-radius));
}
.file-tree__row:hover [data-theme-layout-scope="file-tree-indicator"] {
  background: var(--reader-tree-row-hover);
}
.file-tree__row.is-active [data-theme-layout-scope="file-tree-indicator"],
.file-tree__row.is-selected [data-theme-layout-scope="file-tree-indicator"] {
  background: var(--reader-tree-row-active);
  font-weight: var(--reader-tree-active-weight, 650);
}
.file-tree__disclosure {
  inline-size: var(--reader-file-tree-disclosure-size);
  block-size: var(--reader-file-tree-disclosure-size);
}
.file-tree__icon {
  inline-size: var(--reader-file-tree-icon-size);
  block-size: var(--reader-file-tree-icon-size);
  margin-inline-end: 0.35rem;
}
.file-tree__name {
  min-inline-size: 0;
  white-space: nowrap;
}
.file-tree__indent-guide {
  inline-size: var(--reader-file-tree-indent);
  border-inline-start: var(--reader-tree-guide-width, 1px) solid var(--reader-border);
}
.outline-panel {
  padding: var(--reader-panel-padding);
  border-inline-start: var(--reader-outline-border-width, 1px) solid var(--reader-border);
  background: var(--reader-panel-bg);
  color: var(--reader-text);
  box-shadow: var(--reader-outline-shadow, none);
}
.outline-panel h2 {
  margin-block: 0 0.75rem;
  font-family: var(--reader-heading-font, var(--reader-font-family));
  font-size: var(--reader-outline-title-size, 0.82rem);
}
.outline-panel ul {
  margin: 0;
  padding: 0;
  list-style: none;
}
.outline-panel ul ul {
  margin-inline-start: var(--reader-outline-indent);
}
[data-theme-layout-scope="outline-indicator"] {
  inline-size: 100%;
  padding: var(--reader-outline-row-padding, 5px 7px);
  border-radius: var(--reader-outline-row-radius, var(--reader-control-radius));
  text-align: start;
}
[data-theme-layout-scope="outline-indicator"]:hover {
  background: var(--reader-tree-row-hover);
}
[data-theme-layout-scope="outline-indicator"].is-active {
  background: var(--reader-outline-active-bg);
  font-weight: 700;
}
.outline-panel__resize-handle {
  inline-size: var(--reader-resize-handle-width, 4px);
}
.yaml-reader {
  display: grid;
  gap: var(--reader-dashboard-gap);
  padding: var(--reader-generated-padding, 14px);
  border: var(--reader-generated-border-width, 1px) solid var(--reader-border);
  border-radius: var(--reader-radius);
  background: var(--reader-surface);
}
.json-reader {
  display: grid;
  grid-template-columns: minmax(8rem, 0.32fr) minmax(0, 1fr);
  gap: var(--reader-json-gap, 7px 12px);
  padding: var(--reader-generated-padding, 14px);
  border-radius: var(--reader-radius);
  background: var(--reader-surface);
}
.json-reader .json-key {
  font-family: var(--reader-monospace-font);
  font-weight: 700;
}
.mermaid-fullscreen {
  position: relative;
  padding: var(--reader-mermaid-padding, 18px);
  border: var(--reader-mermaid-border-width, 1px) solid var(--reader-border);
  border-radius: var(--reader-radius);
  background: var(--reader-surface);
}
.mermaid-fullscreen svg {
  max-inline-size: 100%;
}
[data-theme-layout-scope="mermaid-actions"] {
  position: absolute;
  inset: auto 14px 14px auto;
  display: flex;
  gap: 4px;
  padding: 5px;
  border-radius: var(--reader-control-radius);
  background: var(--reader-panel-bg);
  box-shadow: var(--reader-control-shadow);
}
[data-theme-layout-scope="table-actions"] {
  position: absolute;
  inset: 10px 10px auto auto;
  display: grid;
  gap: 4px;
  padding: 5px;
  border-radius: var(--reader-control-radius);
  background: var(--reader-panel-bg);
  box-shadow: var(--reader-control-shadow);
}
.table-fullscreen__body {
  min-block-size: 100%;
  padding: 0;
  background: var(--reader-page-bg);
}
.table-fullscreen__content {
  min-block-size: 100%;
  padding: var(--reader-fullscreen-padding, 18px);
}
[data-theme-layout-scope="table-fullscreen-actions"] {
  position: sticky;
  inset: auto 16px 16px auto;
  inline-size: max-content;
  margin-inline-start: auto;
  padding: 7px;
  border-radius: var(--reader-control-radius);
  background: var(--reader-panel-bg);
  box-shadow: var(--reader-control-shadow);
}
[data-theme-layout-scope="theme-preview-overlay"] {
  position: absolute;
  inset: 10px;
  pointer-events: none;
  border-radius: var(--reader-radius);
}
.document-reader ::selection {
  background: var(--reader-selection-bg);
  text-shadow: none;
}
.reader-layout { border-block-start: 1px solid var(--reader-border); }
.document-reader { border-radius: 0; }
.document-reader .markdown-heading--h1 { margin-block-start: 0.8rem; }
.document-reader .markdown-heading--h2 { padding-block-end: 0.3rem; border-block-end: 1px solid var(--reader-heading-border); }
.document-reader .markdown-quote { border-inline-start-width: 4px; }
.document-reader .markdown-code-block { box-shadow: inset 0 1px var(--reader-surface); }
.document-reader .markdown-table-wrapper { border: 1px solid var(--reader-table-border); }
.document-reader .markdown-table-cell { border-inline-end: 1px solid var(--reader-table-border); }
.document-reader .markdown-table-cell:last-child { border-inline-end: 0; }
.document-reader .callout { border-inline-start-width: 4px; }
.reader-toolbar { display: flex; align-items: center; border-block-end-width: 1px; box-shadow: 0 1px 3px rgb(0 0 0 / 10%); }
[data-theme-layout-scope="toolbar-group"] { padding: 2px; border: 1px solid var(--reader-border); border-radius: 8px; background: var(--reader-surface); }
.reader-toolbar button { border: 0; box-shadow: none; }
.reader-toolbar button + button { border-inline-start: 1px solid var(--reader-border); border-radius: 0; }
.file-tree { border-inline-end: 1px solid var(--reader-border); }
.file-tree__row.is-active [data-theme-layout-scope="file-tree-indicator"] { border-radius: 3px; box-shadow: inset 3px 0 var(--reader-accent); }
.file-tree__disclosure { opacity: 0.72; }
.outline-panel { border-inline-start-width: 1px; }
.outline-panel__resize-handle { background: var(--reader-border); }
[data-theme-layout-scope="outline-indicator"].is-active { border-radius: 4px; }
.yaml-reader, .json-reader { border: 1px solid var(--reader-border); }
[data-theme-layout-scope="table-fullscreen-actions"] { border: 1px solid var(--reader-border); }
